 \label{L: possible weights}
Let $\mathcal{F}$ be a maximal coclique of $\Gamma_{2n}$.
    Let $B$ be an $n$-space of $\mathrm{PG}(2n,q)$ that occurs in a flag of $\mathcal{F}$. There exists a $k\in\{1,\ldots,n+1\}$, such that the number of flags in $\mathcal{F}$ that contain $B$ is precisely $\Gauss{k}{1}$. Furthermore, the number in question is $\Gauss{n+1}{1}$ if and only if every flag $(A',B')\in \mathcal{F}$ satisfies $A'\cap B\neq \emptyset$.

    \label{C: possible weights}
Let $\mathcal{F}$ be a maximal coclique of $\Gamma_{2n}$.
    Let $A$ be an $(n-1)$-space of $\mathrm{PG}(2n,q)$ that occurs in a flag of $\mathcal{F}$. There exists a $k\in\{ 1,\ldots,n+1\}$ such that the number of flags in $\mathcal{F}$ that contain $A$ is $\Gauss{k}{1}$. Furthermore, the number in question is $\Gauss{n+1}{1}$ if and only if every flag $(A',B')\in \mathcal{F}$ satisfies $B'\cap A\neq \emptyset$.

 (\cite{hiltonmilner_vectorspaces, ekr_vectorspaces}) \label{R: EKR + HM vectorspaces}
Let $\mathcal{C}$ be a set of pairwise intersecting $(n-1)$-spaces of $\mathrm{PG}(2n,q)$, with $n\geq 3$ and $q\geq 3$.
Then either $|\mathcal{C}|\leq \Gauss{2n}{n-1}-q^{n(n-1)}\Gauss{n}{1}$, or there exists a point $P$, such that every $(n-1)$-space is incident with $P$.

 \label{R: EKR for n=2k}
  Let $\mathcal{C}$ be a set of pairwise intersecting $(n-1)$-spaces of $\mathrm{PG}(2n-1,q)$. 
  \begin{itemize}
      \item[(a)] (Theorem 5.3.1 in \cite{Newman_PhD_Thesis}) Assume that $\mathcal{C}$ is as large as possible. Then there exists a point or hyperplane in $\mathrm{PG}(2n-1,q)$ that is incident with all $(n-1)$-spaces. In particular, $|\mathcal{C}|=\Gauss{2n-1}{n-1}$.
      \item[(b)]Now assume that $\mathcal{C}$ is a set of pairwise intersecting $(n-1)$-spaces of $\mathrm{PG}(2n-1,q)$, such that that there is no point or hyperplane in $\mathrm{PG}(2n-1,q)$ that is incident with all $(n-1)$-spaces.
          \begin{itemize}
\item[(a)] (Theorem 6 in \cite{Ihringer_Hilton_Milner}) Let $q\geq 4$ and $n\geq 4$. Then $|\mathcal{C}|<3\Gauss{n}{1}\Gauss{2n-2}{n-2}$.
\item[(b)] (Theorem 6.1 in \cite{k=3_Hilton_Milner})
  Let $n=3$. Then $|\mathcal{C}|\leq q^5+2q^4+3q^3+2q^2+q+1$.
\end{itemize}
  \end{itemize}

